                        {"itens":[{"nome":"X","precoUnitario":10,"quantidade":5,"pesoKg":1}],"modalidadeEntrega":"MOTOBOY",
                         "formaPagamento":"PIX","nivelClube":"BRONZE","regiao":"SUL"}"""))
