                {"itens":[{"nome":"X","precoUnitario":100,"quantidade":1,"pesoKg":1}],"modalidadeEntrega":"%s",
                 "cupom":"%s","formaPagamento":"%s","parcelas":%d,"nivelClube":"%s","regiao":"%s"}"""
